# Median footprint of each V02 family row (main slot) vs V11 p50 x main share. Own arithmetic of V2 §3.5 M5's constructions
import math
FWD,BACK=2.25,1.5
SHAPE={}; CUR=None
def fam_area(f,w,L,c):
    if f=='single': return max(L,1.2*w)*w
    if f=='L': Lf=max(L,2*w); Ls=max(L,2*w); return Lf*w+w*(Ls-w)
    if f=='T': Lh=max(L,1.4*w); return Lh*w+w*(FWD+w+BACK)
    if f=='H': Lh=max(L,1.4*w); return Lh*w+2*w*(FWD+w+BACK)
    if f=='U': Lf=max(L,3*w); Ls=max(L,2*w); return Lf*w+2*w*(Ls-w)
    if f=='cross': Lm=max(L,3*w); Lc=max(L,3*w); return Lm*w+w*(Lc-w)
    if f in('rectCourt','plotRing'): S=max(L,2*w+c,3*w); return S*S-(S-2*w)**2
    if f=='gridWalk': p=max(L/2,w+max(2,.3*w)); return 2.5*p*w
    if f=='towerHouse':
        t=1.6*w; sh=SHAPE.get(CUR,{'square':1})
        a=sh.get('square',0)*t*t+sh.get('round',0)*math.pi*(t/2)**2+sh.get('octagon',0)*2*math.sqrt(2)*(t/2)**2
        return a/sum(sh.values()) + (L*w if L>0 else 0)
    raise Exception(f)
