rs=[]
for k,(W,wr,lr,cm,p50,share) in R.items():
    CUR=k
    out=[]
    for i in range(4):
        w=sum(wr[i])/2; L=sum(lr[i])/2; tot=sum(W[i].values())
        med=sum(wt*fam_area(f,w,L,cm[i]) for f,wt in W[i].items())/tot
        r=med/(p50[i]*share); rs.append(r); out.append(f"{med:.0f}/{p50[i]*share:.0f}={r:.2f}")
    print(k, *out)
